import{_ as e,I as a,g as o,j as r}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Workspace Settings","description":"Managing the master hourly rate, global markup, overheads, and local parameters of the current active workspace.","frontmatter":{"title":"Workspace Settings","description":"Managing the master hourly rate, global markup, overheads, and local parameters of the current active workspace.","order":13},"headers":[],"relativePath":"docs/spaces/production/space-settings.md","filePath":"docs/spaces/production/space-settings.md"}'),s={name:"docs/spaces/production/space-settings.md"};function i(n,t,l,c,d,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="⚙️-workspace-settings-the-economic-foundation" tabindex="-1">⚙️ Workspace Settings: The Economic Foundation <a class="header-anchor" href="#⚙️-workspace-settings-the-economic-foundation" aria-label="Permalink to &quot;⚙️ Workspace Settings: The Economic Foundation&quot;">​</a></h1><p>The <strong>&quot;Workspace Settings&quot;</strong> tab is the control center for your business&#39;s profitability. Here, you establish the global norms that are automatically pulled into the Calculator to determine cost prices, influence retail pricing, and distribute indirect expenses fairly across each product.</p><p>These parameters are unique to each workspace. If you manage multiple brands or distinct business lines in PRO mode, each will have its own rate, global markup, and specific overhead expenses.</p><hr><h2 id="⏱️-master-hourly-rate-currency-hour" tabindex="-1">⏱️ Master Hourly Rate (Currency/Hour) <a class="header-anchor" href="#⏱️-master-hourly-rate-currency-hour" aria-label="Permalink to &quot;⏱️ Master Hourly Rate (Currency/Hour)&quot;">​</a></h2><p>This is the cost of your working time. The program uses this figure to automatically calculate labor costs when creating or editing a product recipe.</p><ul><li><strong>How it works:</strong> If crafting a bag is budgeted at a norm of <code>2.5</code> hours, and your rate is set to <code>$80/hour</code>, the program will automatically add <code>$200</code> to the product cost price under &quot;Labor Cost&quot;.</li><li><strong>Why change it:</strong> The rate should reflect your actual skill level, speed, and market rates. Regularly increase it as your skills grow so that your product prices keep pace with your value as an artisan.</li><li><strong>Where it applies:</strong> In all new Calculator estimates and when scheduling manufacturing batches.</li></ul><hr><h2 id="📈-global-markup" tabindex="-1">📈 Global Markup (%) <a class="header-anchor" href="#📈-global-markup" aria-label="Permalink to &quot;📈 Global Markup (%)&quot;">​</a></h2><p>The baseline profit percentage that the program automatically applies to the <strong>total cost price</strong> of an item (materials + labor + overhead expenses) when calculating the recommended retail price.</p><p>$$\\text{Retail Price} = \\text{Total Cost} \\times \\left(1 + \\frac{\\text{Markup}}{100}\\right)$$</p><ul><li><strong>Flexibility:</strong> This value is populated in the Calculator by default, but you can always adjust it manually for specific items (for example, for promotional items or, conversely, limited collections).</li><li><strong>Business value:</strong> The markup is your safety margin. It must cover not only net profit, but also the risks of waste/scraps, seasonal slow periods, and customer acquisition costs.</li></ul><hr><h2 id="📦-overhead-expenses-indirect-costs" tabindex="-1">📦 Overhead Expenses (Indirect Costs) <a class="header-anchor" href="#📦-overhead-expenses-indirect-costs" aria-label="Permalink to &quot;📦 Overhead Expenses (Indirect Costs)&quot;">​</a></h2><p>Business is more than just leather, hardware, and thread. Workshop rent, electricity, advertising, packaging, website hosting, platform transaction fees, and tool depreciation all cost money. In OmniCraft ERP, you can create an unlimited number of overhead cost categories, which will be <strong>automatically allocated to each product</strong>.</p><h3 id="distribution-norm-types" tabindex="-1">Distribution Norm Types <a class="header-anchor" href="#distribution-norm-types" aria-label="Permalink to &quot;Distribution Norm Types&quot;">​</a></h3><p>When adding an overhead category, you select one of two calculation methods:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Norm Type</th><th style="text-align:left;">How It Is Calculated</th><th style="text-align:left;">Best Suited For</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>📊 Percentage (%)</strong></td><td style="text-align:left;">A fraction of the material costs or raw cost price (materials + labor)</td><td style="text-align:left;">Platform commissions, logistics, packaging that scales with product value.</td></tr><tr><td style="text-align:left;"><strong>🏷️ Fixed Amount</strong></td><td style="text-align:left;">A flat monetary sum added to each unit of product</td><td style="text-align:left;">Rent (allocated over expected output), tags, certificates, fixed packing boxes.</td></tr></tbody></table><h3 id="overhead-management" tabindex="-1">Overhead Management <a class="header-anchor" href="#overhead-management" aria-label="Permalink to &quot;Overhead Management&quot;">​</a></h3><ul><li><strong>Adding:</strong> Enter the name, select the norm type, and specify the global value. Click &quot;Add&quot;—the category instantly appears in your list.</li><li><strong>Editing:</strong> You can modify the value or type of norm at any time. The updated parameters will apply to all subsequent estimates.</li><li><strong>Deleting:</strong> If a category is no longer relevant, you can delete it.</li></ul><div class="warning custom-block"><p class="custom-block-title">Important</p><p>Deleting or editing an overhead category <strong>does not recalculate historical sales or pre-existing recipes</strong>. The category simply ceases to be factored into new global cost estimates. This ensures that your past financial reporting remains consistent and historically accurate.</p></div><hr><h2 id="🗓️-date-picker-display-calendar" tabindex="-1">🗓️ Date Picker Display (Calendar) <a class="header-anchor" href="#🗓️-date-picker-display-calendar" aria-label="Permalink to &quot;🗓️ Date Picker Display (Calendar)&quot;">​</a></h2><p>A small but highly convenient interface adjustment. By default, date entry fields in the program are hidden to save screen space and speed up your workflow: the system automatically inputs the current date (&quot;today&quot;).</p><p>If you frequently need to log backdated transactions, schedule future write-offs, or record exact shipment dates, expand this drawer and enable the visual calendar. This setting is saved locally and does not affect your calculations.</p><hr><h2 id="💾-saving-data-accuracy" tabindex="-1">💾 Saving &amp; Data Accuracy <a class="header-anchor" href="#💾-saving-data-accuracy" aria-label="Permalink to &quot;💾 Saving &amp; Data Accuracy&quot;">​</a></h2><p>After making changes, click the <strong>&quot;Save Settings&quot;</strong> button. The program will verify that all numbers are filled out correctly and write them to the active workspace&#39;s database.</p><div class="info custom-block"><p class="custom-block-title">Technical Accuracy</p><p>All financial parameters (labor rate, markup, overhead values) are stored in the database in a <strong>high-precision integer format</strong> (scaled by 10,000). This effectively eliminates rounding errors, &quot;lost cents,&quot; and cumulative discrepancies over years of using the program, even when working with fractional hours or complex percentages.</p></div><hr><h2 id="🧠-how-settings-affect-the-workshop-economy" tabindex="-1">🧠 How Settings Affect the Workshop Economy <a class="header-anchor" href="#🧠-how-settings-affect-the-workshop-economy" aria-label="Permalink to &quot;🧠 How Settings Affect the Workshop Economy&quot;">​</a></h2><p>All three parameters work closely together inside the <strong>Calculator</strong> and directly shape your net profit:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Parameter</th><th style="text-align:left;">What It Affects</th><th style="text-align:left;">Business Consequence of Changing</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Master Hourly Rate</strong></td><td style="text-align:left;">Labor cost component</td><td style="text-align:left;">Increasing the rate accurately raises the &quot;frozen&quot; asset value of completed stock and fairly reflects the value of your labor.</td></tr><tr><td style="text-align:left;"><strong>Overhead Expenses</strong></td><td style="text-align:left;">Total product cost price</td><td style="text-align:left;">Grounds your pricing in reality. Without them, profits appear artificially higher than they are, leading to cash flow shortages.</td></tr><tr><td style="text-align:left;"><strong>Markup</strong></td><td style="text-align:left;">Retail price and gross margin</td><td style="text-align:left;">Directly impacts revenue and average ticket. Setting it too high can lower conversions, while setting it too low undervalues your craftsmanship.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Management Tip</p><p>Avoid changing your global settings too frequently. Large, abrupt adjustments to your rate or overhead costs will distort comparative historical analytics over past periods. It is best to adjust them <strong>once a quarter</strong> or when your business conditions change significantly (e.g., relocating the workshop, substantial changes in logistics rates, or stepping up to a higher tier of craftsmanship).</p></div>',34)])])}const g=e(s,[["render",i]]);export{p as __pageData,g as default};
